-- Espacios escénicos · Latinoamérica completa: los 19 países del ámbito,
-- todo el territorio (hasta ahora solo capitales y grandes ciudades).
-- Fuente: OpenStreetMap (© colaboradores de OpenStreetMap, ODbL), consulta del
-- 2026-10-18. Mismo criterio que España (20261017220000): amenity=theatre o
-- concert_hall con nombre propio, arts_centre solo si el nombre indica teatro
-- o auditorio; fuera anfiteatros y escenarios al aire libre, cines sin teatro,
-- espacios desaparecidos, escuelas, salones de actos y nombres genéricos.
-- Región: primer nivel administrativo de OSM, con los nombres ya usados en la
-- tabla (Región Metropolitana, Bogotá D.C., Asunción…). En Puerto Rico la
-- región es el municipio, como en el lote anterior.
-- No se duplica lo ya cargado: se salta todo espacio con el mismo elemento de
-- OSM o con el mismo nombre a menos de ~300 m de otro del mismo país.

insert into public.espacios_escenicos
  (nombre, tipo, pais_code, region, municipio, web, lat, lon, fuente, fuente_ref, estado, direccion, codigo_postal, telefono, wikidata_id)
